import React, { useEffect, useState, useMemo } from 'react';

/*
 * MatchScoreCard — Glassmorphism circular progress badge
 *
 * Weighted scoring formula displayed:
 *   FinalScore = (Skill_relevance × 0.7) + (Overlap × 0.2) + (Profile_boost × 0.1)
 *
 * Color thresholds:
 *   score ≥ 75  → Green  (High Match)
 *   score 40-74 → Orange (Moderate Match)
 *   score < 40  → Red    (Low Match)
 */

const MatchScoreCard = ({ score = 0, size = 'small' }) => {
  // Animate the arc from 0 → score on mount
  const [displayScore, setDisplayScore] = useState(0);

  useEffect(() => {
    // Small delay so the CSS transition is visible after first paint
    const t = setTimeout(() => setDisplayScore(score), 120);
    return () => clearTimeout(t);
  }, [score]);

  // Per-instance unique IDs to avoid SVG defs collisions when many cards render
  const uid = useMemo(
    () => `msc-${Math.random().toString(36).slice(2, 8)}`,
    []
  );
  const gradId   = `${uid}-grad`;
  const glowId   = `${uid}-glow`;
  const shadowId = `${uid}-shadow`;

  // ── Size config ─────────────────────────────────────────────────────────────
  const sizeConfig = {
    small:  { svgSize: 74,  strokeWidth: 5.5, scoreFontSize: 15, labelFontSize: 9,  padding: '10px 12px' },
    medium: { svgSize: 96,  strokeWidth: 6,   scoreFontSize: 20, labelFontSize: 11, padding: '12px 14px' },
    large:  { svgSize: 136, strokeWidth: 7,   scoreFontSize: 30, labelFontSize: 13, padding: '16px 18px' },
  };
  const cfg    = sizeConfig[size] || sizeConfig.small;
  const center = cfg.svgSize / 2;
  const radius = center - cfg.strokeWidth - 3;
  const circ   = 2 * Math.PI * radius;
  const offset = circ - (displayScore / 100) * circ;

  // ── Theme by score ───────────────────────────────────────────────────────────
  const theme = useMemo(() => {
    if (score >= 75) return {
      gradStart  : '#22c55e',
      gradEnd    : '#4ade80',
      glowColor  : 'rgba(34, 197, 94, 0.55)',
      glowSoft   : 'rgba(34, 197, 94, 0.12)',
      textColor  : '#15803d',
      border     : 'rgba(34, 197, 94, 0.30)',
      bgTint     : 'rgba(34, 197, 94, 0.07)',
      label      : 'High Match',
      trackStroke: 'rgba(34, 197, 94, 0.12)',
    };
    if (score >= 40) return {
      gradStart  : '#f97316',
      gradEnd    : '#fbbf24',
      glowColor  : 'rgba(249, 115, 22, 0.55)',
      glowSoft   : 'rgba(249, 115, 22, 0.12)',
      textColor  : '#c2410c',
      border     : 'rgba(249, 115, 22, 0.30)',
      bgTint     : 'rgba(249, 115, 22, 0.07)',
      label      : 'Moderate',
      trackStroke: 'rgba(249, 115, 22, 0.12)',
    };
    return {
      gradStart  : '#ef4444',
      gradEnd    : '#f87171',
      glowColor  : 'rgba(239, 68, 68, 0.55)',
      glowSoft   : 'rgba(239, 68, 68, 0.12)',
      textColor  : '#b91c1c',
      border     : 'rgba(239, 68, 68, 0.30)',
      bgTint     : 'rgba(239, 68, 68, 0.07)',
      label      : 'Low Match',
      trackStroke: 'rgba(239, 68, 68, 0.12)',
    };
  }, [score]);

  return (
    <div
      className="animate-bounce-in inline-flex flex-col items-center justify-center relative overflow-hidden"
      title={`Match Score: ${Math.round(score)}% — Formula: (Skills×0.7) + (Overlap×0.2) + (Profile×0.1)`}
      style={{
        borderRadius       : '18px',
        padding            : cfg.padding,
        /* Glassmorphism */
        background         : `rgba(255, 255, 255, 0.55)`,
        backdropFilter     : 'blur(18px) saturate(200%)',
        WebkitBackdropFilter: 'blur(18px) saturate(200%)',
        border             : `1.5px solid ${theme.border}`,
        boxShadow          : `
          0 4px 24px ${theme.glowSoft},
          0 1px 4px rgba(0,0,0,0.06),
          inset 0 1px 0 rgba(255,255,255,0.70)
        `,
        transition         : 'box-shadow 0.3s ease, transform 0.3s ease',
      }}
      onMouseEnter={e => {
        e.currentTarget.style.transform = 'translateY(-2px) scale(1.04)';
        e.currentTarget.style.boxShadow = `0 10px 36px ${theme.glowColor}, 0 2px 8px rgba(0,0,0,0.08), inset 0 1px 0 rgba(255,255,255,0.70)`;
      }}
      onMouseLeave={e => {
        e.currentTarget.style.transform = 'translateY(0) scale(1)';
        e.currentTarget.style.boxShadow = `0 4px 24px ${theme.glowSoft}, 0 1px 4px rgba(0,0,0,0.06), inset 0 1px 0 rgba(255,255,255,0.70)`;
      }}
    >
      {/* Soft color tint wash */}
      <div
        aria-hidden="true"
        style={{
          position       : 'absolute',
          inset          : 0,
          borderRadius   : '18px',
          background     : theme.bgTint,
          pointerEvents  : 'none',
        }}
      />

      {/* ── SVG Circular Progress ─────────────────────────────────────── */}
      <div style={{ position: 'relative', width: cfg.svgSize, height: cfg.svgSize }}>
        <svg
          width={cfg.svgSize}
          height={cfg.svgSize}
          viewBox={`0 0 ${cfg.svgSize} ${cfg.svgSize}`}
          style={{ transform: 'rotate(-90deg)', display: 'block' }}
          aria-hidden="true"
        >
          <defs>
            {/* Gradient stroke for the progress arc */}
            <linearGradient id={gradId} x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%"   stopColor={theme.gradStart} />
              <stop offset="100%" stopColor={theme.gradEnd}   />
            </linearGradient>

            {/* Soft glow blur filter */}
            <filter id={glowId} x="-30%" y="-30%" width="160%" height="160%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="blurred" />
            </filter>

            {/* Drop-shadow filter for the card-level svg depth */}
            <filter id={shadowId} x="-10%" y="-10%" width="120%" height="120%">
              <feDropShadow dx="0" dy="0" stdDeviation="2" floodColor={theme.gradStart} floodOpacity="0.35" />
            </filter>
          </defs>

          {/* ① Background track */}
          <circle
            cx={center}
            cy={center}
            r={radius}
            fill="none"
            stroke={theme.trackStroke}
            strokeWidth={cfg.strokeWidth}
          />

          {/* ② Glow halo (blurred, rendered behind main arc) */}
          {displayScore > 0 && (
            <circle
              cx={center}
              cy={center}
              r={radius}
              fill="none"
              stroke={theme.gradStart}
              strokeWidth={cfg.strokeWidth + 3}
              strokeDasharray={circ}
              strokeDashoffset={offset}
              strokeLinecap="round"
              filter={`url(#${glowId})`}
              opacity={0.40}
              style={{
                transition: 'stroke-dashoffset 1.2s cubic-bezier(0.22, 1, 0.36, 1)',
              }}
            />
          )}

          {/* ③ Main progress arc */}
          <circle
            cx={center}
            cy={center}
            r={radius}
            fill="none"
            stroke={`url(#${gradId})`}
            strokeWidth={cfg.strokeWidth}
            strokeDasharray={circ}
            strokeDashoffset={offset}
            strokeLinecap="round"
            filter={`url(#${shadowId})`}
            style={{
              transition: 'stroke-dashoffset 1.2s cubic-bezier(0.22, 1, 0.36, 1)',
            }}
          />
        </svg>

        {/* ── Center label ──────────────────────────────────────────── */}
        <div
          style={{
            position       : 'absolute',
            inset          : 0,
            display        : 'flex',
            flexDirection  : 'column',
            alignItems     : 'center',
            justifyContent : 'center',
            gap            : '1px',
          }}
        >
          <span
            style={{
              fontSize  : cfg.scoreFontSize,
              fontWeight: 900,
              color     : theme.textColor,
              lineHeight: 1,
              letterSpacing: '-0.5px',
            }}
          >
            {Math.round(score)}%
          </span>
        </div>
      </div>

      {/* ── Score label ───────────────────────────────────────────────── */}
      <p
        style={{
          marginTop  : '5px',
          fontSize   : cfg.labelFontSize,
          fontWeight : 700,
          color      : theme.textColor,
          letterSpacing: '0.3px',
          textAlign  : 'center',
          lineHeight : 1,
          position   : 'relative', // above the tint layer
        }}
      >
        {theme.label}
      </p>
    </div>
  );
};

export default MatchScoreCard;
